def cobs_encode(data):
    out = bytearray()
    code_index = 0
    out.append(0)
    code = 1
    for b in data:
        if b == 0:
            out[code_index] = code
            code_index = len(out)
            out.append(0)
            code = 1
        else:
            out.append(b)
            code += 1
            if code == 255:
                out[code_index] = 255
                code_index = len(out)
                out.append(0)
                code = 1
    out[code_index] = code
    return bytes(out)

def cobs_decode(data):
    if not data:
        raise ValueError("empty input")
    if any(b == 0 for b in data):
        raise ValueError("zero byte in encoded data")
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        code = data[i]
        i += 1
        if code == 0:
            raise ValueError("zero code byte")
        if i + code - 1 > n:
            raise ValueError("group data runs past end")
        out.extend(data[i:i+code-1])
        i += code - 1
        if code < 255:
            if i < n:
                out.append(0)
        else:
            if i == n:
                raise ValueError("trailing 255 code without next group")
    return bytes(out)
